@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{color-scheme:dark;--cyan:#69f5e1;--pink:#ff548e;--gold:#ffcf6d;--ink:#111325}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0d1020;font-family:'Barlow Condensed',Impact,sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}.game-shell{position:relative;width:min(100vw,177.78vh);height:min(100vh,56.25vw);margin:auto;top:50%;transform:translateY(-50%);overflow:hidden;background:#111426;box-shadow:0 20px 100px #000b;border:1px solid #434359}canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.scanlines{pointer-events:none;position:absolute;inset:0;opacity:.13;background:repeating-linear-gradient(0deg,transparent 0 3px,#101020 4px 5px);mix-blend-mode:multiply}.top-hud{position:absolute;top:3.3%;left:3.2%;right:3.2%;display:flex;align-items:flex-start;justify-content:space-between;z-index:2;pointer-events:none;text-shadow:0 2px 6px #101020}.player-card{display:flex;gap:12px;width:28%;align-items:center}.portrait{width:53px;height:53px;border:2px solid var(--cyan);background:linear-gradient(145deg,#304559,#142031);color:var(--cyan);font-size:37px;font-weight:900;display:grid;place-items:center;clip-path:polygon(0 0,100% 0,100% 75%,76% 100%,0 100%);text-shadow:2px 2px #e9447c}.player-info{width:calc(100% - 65px)}.eyebrow,.small-label,.combo,.controls-hint,.overlay-note,.overlay-foot{font-family:'DM Mono',monospace;letter-spacing:.11em}.eyebrow{font-size:11px;color:#d9d7e8}.eyebrow span{color:var(--gold);margin-left:7px}.health-track,.boss-track{height:11px;background:#231f36;border:1px solid #66607c;padding:2px;margin:5px 0 2px}.health-fill{height:100%;width:100%;background:linear-gradient(90deg,#ff4b80,#ff9a79);transition:width .18s}.small-label{font-size:9px;color:#b8b4c9}.stage-card{text-align:center;min-width:220px}.stage-title{font-size:22px;font-weight:900;letter-spacing:.08em;color:#fff;text-shadow:0 0 18px #65d8d1}.stage-progress{height:3px;background:#24253d;margin-top:8px}.stage-progress span{display:block;width:0;height:100%;background:var(--cyan);transition:width .3s}.score-card{text-align:right;width:28%}.score-value{font-size:24px;font-weight:900;letter-spacing:.08em;color:var(--gold)}.combo{font-size:9px;color:var(--cyan);min-height:12px}.boss-hud{display:none;position:absolute;z-index:3;top:13%;left:30%;right:30%;text-align:center;text-shadow:0 2px 5px #000}.boss-hud.visible{display:block}.boss-name{font-size:14px;letter-spacing:.18em;color:#fff}.boss-track{height:12px;border-color:#a44d78;background:#301c36}.boss-fill{height:100%;width:100%;background:linear-gradient(90deg,#fc477c,#ffb348);transition:width .2s}.controls-hint{position:absolute;bottom:2.4%;left:50%;transform:translateX(-50%);font-size:9px;white-space:nowrap;color:#c0bbcf;z-index:2;text-shadow:0 2px #000}.controls-hint span{color:var(--cyan)}.controls-hint i{color:#706c86;font-style:normal;padding:0 7px}.overlay{position:absolute;z-index:5;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;background:linear-gradient(90deg,#111326eF,#17142ae8 50%,#171326ed);text-align:center;color:#fff;transition:opacity .25s}.overlay.hidden{opacity:0;pointer-events:none}.title-mark{margin-top:-2%}.title-kicker{font:10px 'DM Mono',monospace;letter-spacing:.42em;color:var(--cyan);margin-bottom:9px}.title-mark h1{font-size:clamp(60px,10vw,128px);line-height:.77;margin:0;font-weight:900;letter-spacing:-.03em;color:#f5f0ec;text-shadow:5px 5px #e34276,10px 10px #312c4d}.title-mark h1 em{font-style:normal;color:var(--cyan);text-shadow:5px 5px #e34276,10px 10px #312c4d}.title-rule{display:flex;align-items:center;gap:16px;justify-content:center;color:#ffb75e;font-size:12px;letter-spacing:.36em;margin-top:25px}.title-rule span{height:1px;width:55px;background:#ffb75e}.intro-copy{font-size:19px;color:#cac7d5;margin:22px 0 18px}.intro-copy strong{color:#fff}.stage-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:7px;max-width:760px;margin:0 20px 25px}.stage-chips span{font:9px 'DM Mono',monospace;color:#c0bed2;border:1px solid #48445d;background:#1a1b30;padding:7px 9px;letter-spacing:.06em}.start-button{cursor:pointer;border:0;color:#171326;background:var(--gold);padding:14px 28px;font:900 19px 'Barlow Condensed',sans-serif;letter-spacing:.09em;box-shadow:5px 5px #ed5384;transition:transform .12s,filter .12s}.start-button b{margin-left:17px;font-size:14px}.start-button:active{transform:translate(3px,3px);box-shadow:2px 2px #ed5384}.overlay-note{font-size:9px;color:#c2bfd0;margin-top:22px;letter-spacing:.07em}.overlay-note kbd{font:10px 'DM Mono',monospace;background:#2c2a42;border:1px solid #55516a;padding:3px 5px;color:var(--cyan)}.overlay-foot{position:absolute;bottom:4%;font-size:9px;color:#aaa6ba;letter-spacing:.19em}.overlay-foot i{font-style:normal;color:var(--pink);padding:0 10px}.pause-screen{display:none;position:absolute;z-index:6;inset:0;background:#101222c9;align-items:center;justify-content:center;text-align:center}.pause-screen.visible{display:flex}.pause-box{padding:35px 48px;background:#19192beF;border:1px solid #48445e;box-shadow:8px 8px #ea4d7a}.pause-box h2{font-size:56px;margin:3px;color:var(--cyan)}.pause-box p{color:#c3bfd1;margin:0 0 22px}.toast{position:absolute;z-index:4;top:23%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#18182bdc;border:1px solid #ffcc70;color:#ffe29b;padding:9px 16px;font:11px 'DM Mono',monospace;letter-spacing:.13em;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-controls{display:none;position:absolute;z-index:4;bottom:7%;left:4%;right:4%;justify-content:space-between;align-items:end;pointer-events:none}.dpad{width:150px;height:130px;position:relative;pointer-events:auto}.dpad button,.action{position:absolute;border:1px solid #d5f6ef66;color:#edfff9;background:#152133b8;backdrop-filter:blur(4px);touch-action:none;box-shadow:0 3px 0 #070b17;font-family:inherit}.dpad button{width:44px;height:43px;border-radius:12px;font-size:19px}.dpad button:active,.action:active,.action.active{background:#51ddc9;color:#11152a}.dpad .up{left:52px;top:0}.dpad .left{left:4px;top:45px}.dpad .down{left:52px;top:45px}.dpad .right{left:100px;top:45px}.action-pad{display:flex;gap:12px;align-items:end;pointer-events:auto}.action{position:relative;width:67px;height:67px;border-radius:50%;font-size:27px;color:var(--gold);border-color:#ffcf6d80}.action small{display:block;font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#fff}.action.special{width:56px;height:56px;color:var(--cyan);border-color:#69f5e180}.action.special small{font-size:7px}.action.attack{margin-bottom:15px}.action.special{margin-bottom:0}@media (pointer:coarse),(max-width:800px){.touch-controls{display:flex}.controls-hint{display:none}.top-hud{top:2%;left:3%;right:3%}.portrait{width:40px;height:40px;font-size:28px}.player-card{gap:7px}.eyebrow{font-size:8px}.health-track{height:9px}.small-label{font-size:7px}.stage-title{font-size:15px}.stage-card{min-width:125px}.stage-progress{margin-top:4px}.score-value{font-size:18px}.combo{font-size:7px}.boss-hud{top:12%;left:25%;right:25%}.boss-name{font-size:10px}.boss-track{height:10px}.title-kicker{font-size:8px;letter-spacing:.25em}.title-mark h1{font-size:clamp(54px,13vw,100px)}.title-rule{margin-top:17px}.intro-copy{font-size:16px;margin:16px 0 12px}.stage-chips{gap:4px;margin-bottom:14px}.stage-chips span{font-size:7px;padding:5px}.start-button{font-size:16px;padding:11px 22px}.overlay-note{font-size:7px;margin-top:15px}.overlay-foot{font-size:7px}.toast{top:22%;font-size:9px}}
@media (max-width:520px){.top-hud{align-items:flex-start}.player-card,.score-card{width:30%}.stage-card{min-width:90px;padding-top:1px}.stage-title{font-size:12px}.stage-card .eyebrow{font-size:7px}.score-value{font-size:15px}.portrait{width:32px;height:32px;font-size:22px}.player-card{gap:5px}.small-label{display:none}.health-track{margin-top:4px}.touch-controls{bottom:4%}.dpad{transform:scale(.8);transform-origin:bottom left}.action{width:56px;height:56px}.action.special{width:48px;height:48px}.action-pad{gap:7px}.title-mark h1{font-size:58px}.stage-chips{max-width:330px}.stage-chips span{font-size:6px}.intro-copy{font-size:14px}.overlay-foot{bottom:2%}.overlay-note{font-size:6px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 1280, H = 720, floorTop = 470;
  const $ = id => document.getElementById(id);
  const ui = { overlay:$('overlay'), start:$('startBtn'), boss:$('bossHud'), bossFill:$('bossFill'), bossName:$('bossName'), health:$('healthFill'), healthText:$('healthText'), lives:$('lives'), score:$('score'), stage:$('stageTitle'), stageNo:$('stageEyebrow'), progress:$('stageProgress'), combo:$('combo'), toast:$('toast'), pause:$('pauseScreen') };
  const stages = [
    { name:'THE LAST BELL', boss:'THE HEADMASTER', archetype:'headmaster', sky:['#22284a','#605070'], ground:'#35344a', trim:'#e3ae74', back:'school', foe:['hall monitor','hall monitor','hall monitor','hall monitor','hall monitor'] },
    { name:'NIGHT SHIFT', boss:'ROADHOUSE REX', archetype:'biker', sky:['#151c39','#682f51'], ground:'#292b41', trim:'#f36c84', back:'street', foe:['street punk','street punk','street punk','street punk','street punk'] },
    { name:'AFTER HOURS', boss:'MALL RAT MAX', archetype:'mall', sky:['#29385d','#885476'], ground:'#34334b', trim:'#76eed3', back:'mall', foe:['mall punk','mall punk','mall punk','mall punk','mall punk'] },
    { name:'DEAD AIR', boss:'THE FOREMAN', archetype:'foreman', sky:['#1b2b3d','#615359'], ground:'#34343c', trim:'#ffb861', back:'build', foe:['site bruiser','site bruiser','site bruiser','site bruiser','site bruiser'] },
    { name:'SIGNAL LOST', boss:'THE BROADCASTER', archetype:'broadcast', sky:['#17172e','#603c64'], ground:'#302b43', trim:'#ff588c', back:'hall', foe:['signal thug','signal thug','signal thug','signal thug','signal thug'] }
  ];
  let mode='title', stageIndex=0, player, enemies=[], pickups=[], particles=[], targets=[], elapsed=0, spawnTimer=0, spawned=0, defeated=0, score=0, combo=0, comboTimer=0, camera=0, toastTimer=0, bonusTime=0, bonusIndex=0, lastTime=0, shake=0, powerCooldown=0, tick=0;
  const keys = new Set();
  const stagesPlayed = 5;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const rand=(a,b)=>a+Math.random()*(b-a);
  const stage=()=>stages[stageIndex];
  function freshPlayer(){return {x:210,y:575,z:0,vz:0,face:1,hp:100,lives:3,iframes:0,attack:0,power:0,walk:0,hitFlash:0};}
  function message(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.6;}
  function enterStage(i){stageIndex=i;mode='play';elapsed=0;spawned=defeated=0;spawnTimer=.9;enemies=[];pickups=[];targets=[];camera=0;ui.boss.classList.remove('visible');ui.stage.textContent=stage().name;ui.stageNo.textContent=`STAGE 0${i+1}`;message(`${stage().name} — KEEP MOVING`);}
  function newGame(){player=freshPlayer();score=0;combo=0;powerCooldown=0;particles=[];enterStage(0);ui.overlay.classList.add('hidden');ui.pause.classList.remove('visible');updateHud();}
  function showEnd(win){mode=win?'won':'over';ui.boss.classList.remove('visible');ui.overlay.classList.remove('hidden');ui.overlay.querySelector('.title-kicker').textContent=win?'CITY LIBERATED':'THE RIOT ENDS HERE';ui.overlay.querySelector('h1').innerHTML=win?'YOU <em>WIN</em>':'GAME <em>OVER</em>';ui.overlay.querySelector('.title-rule').innerHTML='<span></span> '+(win?'A NEW LEGEND':'ONE MORE ROUND?')+' <span></span>';ui.overlay.querySelector('.intro-copy').innerHTML=win?`Final score: <strong>${String(score).padStart(6,'0')}</strong> — the city remembers.`:`Final score: <strong>${String(score).padStart(6,'0')}</strong> — take another shot.`;ui.overlay.querySelector('.stage-chips').innerHTML=win?'<span>5 STAGES CLEARED</span><span>4 RIVALS DOWN</span><span>THE SIGNAL IS YOURS</span>':'<span>THE CITY STILL NEEDS YOU</span><span>5 STAGES</span><span>ONE MORE TRY</span>';ui.start.innerHTML='PLAY AGAIN <b>▶</b>';ui.overlay.querySelector('.overlay-note').textContent='MOVE WASD / ARROWS   STRIKE J   POWER K';}
  function enterBonus(){mode='bonus';bonusIndex++;bonusTime=22;targets=[];enemies=[];pickups=[];ui.boss.classList.remove('visible');for(let i=0;i<8;i++)targets.push({x:180+i*132,y:rand(520,590),w:43,h:43,hp:1,phase:rand(0,6),alive:true});ui.stage.textContent=bonusIndex===1?'BONUS: SMASH THE CRATES':'BONUS: BREAK THE SIGNAL';ui.stageNo.textContent=`BONUS 0${bonusIndex}`;message('BONUS ROUND — SMASH 8 TARGETS!');}
  function afterBonus(){if(bonusIndex===1)enterStage(2);else enterStage(4);}
  function stageClear(){score+=1000;updateHud();if(stageIndex===1||stageIndex===3){enterBonus();return;}if(stageIndex===4){showEnd(true);return;}enterStage(stageIndex+1);}
  function spawnEnemy(boss=false){const s=stage();const hp=boss?240+stageIndex*25:42+stageIndex*4;const e={x:rand(960,1150),y:rand(520,603),face:-1,hp,maxHp:hp,boss,name:s.boss,type:boss?s.archetype:'thug',label:boss?s.boss:s.foe[Math.min(spawned,s.foe.length-1)],attack:rand(.8,1.8),stun:0,flash:0,walk:rand(0,6),dead:false};enemies.push(e);if(boss){ui.bossName.textContent=s.boss;ui.boss.classList.add('visible');message(`${s.boss} — STEP UP!`);}}
  function spawnDrop(x,y){const r=Math.random();if(r<.27){let type=r<.105?'heal':r<.19?'star':'life';pickups.push({x,y,type,life:12,bob:rand(0,6)});}}
  function puff(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-190,190),vy:rand(-230,80),life:rand(.25,.55),max:.55,color,size:rand(3,8)});}
  function hurtEnemy(e,damage,sourceX){if(e.dead)return;e.hp-=damage;e.flash=.15;e.stun=e.boss?.23:.36;e.face=e.x<sourceX?1:-1;puff(e.x,e.y-35,e.boss?'#ff648b':'#ffd16e',7);shake=Math.max(shake,e.boss?7:4);if(e.hp<=0){e.dead=true;defeated++;combo++;comboTimer=2.2;score+=e.boss?1500:150+(combo>1?combo*10:0);spawnDrop(e.x,e.y);if(e.boss){ui.boss.classList.remove('visible');setTimeout(()=>{if(mode==='play'&&stageIndex>=0&&enemies.every(v=>v.dead))stageClear();},600);}updateHud();}}
  function attack(power=false){if(mode!=='play'&&mode!=='bonus')return;if(!player)return;if(!power&&player.attack>0)return;if(power&&powerCooldown>0)return;if(power){player.power=.55;player.iframes=Math.max(player.iframes,.65);powerCooldown=6;shake=12;puff(player.x,player.y-28,'#69f5e1',28);message('RIOT BREAKER!');}else player.attack=.28;
    if(mode==='bonus'){let hit=targets.find(t=>t.alive&&Math.abs(t.x-player.x)<110&&Math.abs(t.y-player.y)<65);if(hit){hit.alive=false;score+=100;puff(hit.x,hit.y-20,'#ffc56b',14);if(targets.every(t=>!t.alive)){bonusTime=0;player.lives++;player.hp=Math.min(100,player.hp+35);message('PERFECT! +1 LIFE +35 HP');setTimeout(afterBonus,1100);}}return;}
    let candidates=enemies.filter(e=>!e.dead&&Math.abs(e.x-player.x)<(power?210:105)&&Math.abs(e.y-player.y)<(power?100:54)&&((e.x-player.x)*player.face>-26));if(power){candidates=enemies.filter(e=>!e.dead&&Math.abs(e.x-player.x)<210&&Math.abs(e.y-player.y)<105);}for(const e of candidates)hurtEnemy(e,power?100:(e.boss?24:38),player.x);
  }
  function damagePlayer(amount,sourceX){if(player.iframes>0)return;player.hp-=amount;player.iframes=1.05;player.hitFlash=.28;shake=8;puff(player.x,player.y-28,'#ff577d',9);player.face=sourceX<player.x?1:-1;combo=0;if(player.hp<=0){player.lives--;if(player.lives<=0){player.hp=0;updateHud();setTimeout(()=>showEnd(false),500);}else{player.hp=65;player.iframes=2;message('KNOCKED DOWN — GET BACK UP!');}}updateHud();}
  function updateHud(){if(!player)return;ui.health.style.width=`${clamp(player.hp,0,100)}%`;ui.healthText.textContent=`${Math.ceil(player.hp)} / 100`;ui.lives.textContent=`× ${player.lives}`;ui.score.textContent=String(score).padStart(6,'0');ui.combo.textContent=combo>1?`${combo} HIT COMBO`:(powerCooldown>0?`POWER ${Math.ceil(powerCooldown)}s`:'READY TO FIGHT');const progress=mode==='bonus'?100:(defeated/6)*100;ui.progress.style.width=`${clamp(progress,0,100)}%`;if(enemies.some(e=>e.boss&&!e.dead)){let b=enemies.find(e=>e.boss&&!e.dead);ui.bossFill.style.width=`${Math.max(0,b.hp/b.maxHp*100)}%`;}}
  function update(dt){tick+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}if(mode!=='play'&&mode!=='bonus')return;elapsed+=dt;if(powerCooldown>0)powerCooldown=Math.max(0,powerCooldown-dt);if(player.attack>0)player.attack=Math.max(0,player.attack-dt);if(player.power>0)player.power=Math.max(0,player.power-dt);if(player.iframes>0)player.iframes-=dt;if(player.hitFlash>0)player.hitFlash-=dt;
    let dx=0,dy=0;if(keys.has('left'))dx--;if(keys.has('right'))dx++;if(keys.has('up'))dy--;if(keys.has('down'))dy++;let len=Math.hypot(dx,dy)||1;dx/=len;dy/=len;player.x=clamp(player.x+dx*245*dt,55,1225);player.y=clamp(player.y+dy*170*dt,floorTop+45,632);if(dx)player.face=dx>0?1:-1;if(dx||dy)player.walk+=dt*11;else player.walk*=.8;
    if(mode==='bonus'){bonusTime-=dt;targets.forEach(t=>t.phase+=dt);if(bonusTime<=0){player.hp=Math.min(100,player.hp+15);message('BONUS COMPLETE — +15 HP');setTimeout(afterBonus,1000);bonusTime=-99;}updateHud();}
    else{const living=enemies.filter(e=>!e.dead);if(defeated<5&&spawned<5){spawnTimer-=dt;if(spawnTimer<=0&&living.length<3){spawnEnemy();spawned++;spawnTimer=1.55+rand(.4,1.1);}}if(defeated>=5&&spawned>=5&&!living.length&&!enemies.some(e=>e.boss)){spawnEnemy(true);}
      enemies.forEach(e=>{if(e.dead)return;e.walk+=dt*5;if(e.flash>0)e.flash-=dt;if(e.stun>0){e.stun-=dt;return;}let ex=player.x-e.x,ey=player.y-e.y;e.face=ex>0?1:-1;if(Math.abs(ex)>68||Math.abs(ey)>28){e.x+=Math.sign(ex)*(e.boss?62:78)*dt;e.y+=Math.sign(ey)*Math.min(Math.abs(ey),36)*dt;}else{e.attack-=dt;if(e.attack<=0){e.attack=e.boss?1.15:1.55;if(Math.random()<.78)damagePlayer(e.boss?14:8,e.x);}}});
      // A guaranteed supply crate keeps the first run understandable; later drops are random.
      if(elapsed>15&&elapsed<15+dt){pickups.push({x:player.x+180,y:player.y,type:'heal',life:15,bob:0});}
    }
    pickups.forEach(p=>{p.life-=dt;p.bob+=dt*4;if(Math.abs(p.x-player.x)<35&&Math.abs(p.y-player.y)<48){p.life=0;if(p.type==='heal'){player.hp=Math.min(100,player.hp+35);message('VITALITY +35');}else if(p.type==='star'){player.iframes=6;message('INVINCIBLE — GO WILD!');}else{player.lives++;message('EXTRA LIFE +1');}score+=100;updateHud();}});pickups=pickups.filter(p=>p.life>0);
    particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=380*dt;});particles=particles.filter(p=>p.life>0);shake=Math.max(0,shake-dt*20);camera+=(player.x-640-camera)*dt*.6;updateHud();}
  function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}

