  function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
  function drawBackground(){const s=stage()||stages[0],bg=s.back;let grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,s.sky[0]);grad.addColorStop(.63,s.sky[1]);grad.addColorStop(1,s.ground);ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
    // Distant skyline, clouds, and ambient glow.
    ctx.globalAlpha=.23;ctx.fillStyle=s.trim;ctx.beginPath();ctx.arc(1030,210,115,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
    for(let i=0;i<11;i++){let x=((i*151-camera*.14)%1450+1450)%1450-80,h=125+(i*73%170),y=455-h;ctx.fillStyle=i%2?'#1a2038':'#20223d';ctx.fillRect(x,y,120,h);for(let wy=y+18;wy<450;wy+=24)for(let wx=x+12;wx<x+108;wx+=25){ctx.fillStyle=(i+Math.floor(wy/24))%3?'#e4ad7655':'#78e6d355';ctx.fillRect(wx,wy,8,11);}}
