  function drawFighter(x,y,face,walk=0,attack=0,invincible=false,boss=false,type='thug',flash=0){ctx.save();ctx.translate(x,y);ctx.scale(face,1);const bob=Math.sin(walk)*2, limb=Math.sin(walk)*7;ctx.globalAlpha=.32;ctx.fillStyle='#070914';ctx.beginPath();ctx.ellipse(0,2,27,8,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
