    ctx.fillStyle='#d99a76';ctx.beginPath();ctx.arc(0,-78+bob,13,0,Math.PI*2);ctx.fill();ctx.fillStyle=type==='headmaster'?'#ddd0b5':type==='broadcast'?'#171a2c':'#252237';ctx.beginPath();ctx.arc(0,-82+bob,14,Math.PI,Math.PI*2);ctx.lineTo(13,-77+bob);ctx.lineTo(-12,-76+bob);ctx.fill();ctx.fillStyle='#fff0d9';ctx.fillRect(5,-80+bob,4,2);
