  function keyDown(e){const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='p'||k==='escape'){if(mode==='play'||mode==='bonus'){mode='paused';ui.pause.classList.add('visible');}else if(mode==='paused'){mode='play';ui.pause.classList.remove('visible');}return;}if(k==='j'||k===' '){if(!keys.has('attack'))attack(false);keys.add('attack');return;}if(k==='k'){if(!keys.has('special'))attack(true);keys.add('special');return;}const map={arrowleft:'left',a:'left',arrowright:'right',d:'right,',arrowup:'up',w:'up',arrowdown:'down',s:'down'};if(map[k])keys.add(map[k].replace(',',''));}
  function keyUp(e){let k=e.key.toLowerCase();const map={arrowleft:'left',a:'left',arrowright:'right',d:'right',arrowup:'up',w:'up',arrowdown:'down',s:'down',j:'attack',' ':'attack',k:'special'};if(map[k])keys.delete(map[k]);}
