  document.querySelectorAll('.dpad button').forEach(btn=>{const key=btn.dataset.key;const down=e=>{e.preventDefault();keys.add(key);btn.setPointerCapture?.(e.pointerId);};const up=e=>{e.preventDefault();keys.delete(key);};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up);});
  function bindAction(id,fn,key){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();fn();el.classList.add('active');el.setPointerCapture?.(e.pointerId);});const up=()=>el.classList.remove('active');el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('lostpointercapture',up);}
  bindAction('attackBtn',()=>attack(false));bindAction('specialBtn',()=>attack(true));ui.start.addEventListener('click',newGame);$('resumeBtn').addEventListener('click',()=>{mode='play';ui.pause.classList.remove('visible');});
  canvas.addEventListener('contextmenu',e=>e.preventDefault());
  player=freshPlayer();updateHud();requestAnimationFrame(frame);
})();

