x}.stage-chips span{font:9px 'DM Mono',monospace;color:#c0bed2;border:1px solid #48445d;background:#1a1b30;padding:7px 9px;letter-spacing:.06em}.start-button{cursor:pointer;border:0;color:#171326;background:var(--gold);padding:14px 28px;font:900 19px 'Barlow Condensed',sans-serif;letter-spacing:.09em;box-shadow:5px 5px #ed5384;transition:transform .12s,filter .12s}.start-button b{margin-left:17px;font-size:14px}.start-button:active{transform:translate(3px,3px);box-shadow:2px 2px #ed5384}.overlay-note{font-size:9px;color:#c2bfd0;margin-top:22px;letter-spacing:.07em}.overlay-note kbd{font:10px 'DM Mono',monospace;background:#2c2a42;border:1px solid #55516a;padding:3px 5px;color:var(--cyan)}.overlay-foot{position:absolute;bottom:4%;font-size:9px;color:#aaa6ba;letter-spacing:.19em}.overlay-foot i{font-style:normal;color:var(--pink);padding:0 10px}.pause-screen{display:none;position:absolute;z-index:6;inset:0;background:#101222c9;align-items:center;justify-content:center;text-align:center}.pause-screen.visible{display:flex}.pause-box{padding:35px 48px;background:#19192beF;border:1px solid #48445e;box-shadow:8px 8px #ea4d7a}.pause-box h2{font-size:56px;margin:3px;color:var(--cyan)}.pause-box p{color:#c3bfd1;margin:0 0 22px}.toast{position:absolute;z-index:4;top:23%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#18182bdc;border:1px solid #ffcc70;color:#ffe29b;padding:9px 16px;font:11px 'DM Mono',monospace;letter-spacing:.13em;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-controls{display:none;position:absolute;z-index:4;bottom:7%;left:4%;right:4%;justify-content:space-between;align-items:end;pointer-events:none}.dpad{width:150px;height:130px;position:relative;pointer-events:auto}.dpad button,.action{position:absolute;border:1px solid #d5f6ef66;color:#edfff9;background:#152133b8;backdrop-filter:blur(4px);touch-action:none;box-shadow:0 3px 0 #070b17;font-family:inherit}.dpad button{width:44px;height:43px;border-radius:12px;font-size:19px}.dpad button:active,.action:active,.action.active{background:#51ddc9;color:#11152a}.dpad .up{left:52px;top:0}.dpad .left{left:4px;top:45px}.dpad .down{left:52px;top:45px}.dpad .right{left:100px;top:45px}.action-pad{display:flex;gap:12px;align-items:end;pointer-events:auto}.action{position:relative;width:67px;height:67px;border-radius:50%;font-size:27px;color:var(--gold);border-color:#ffcf6d80}.action small{display:block;font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#fff}.action.special{width:56px;height:56px;color:var(--cyan);border-color:#69f5e180}.action.special small{font-size:7px}.action.attack{margin-bottom:15px}.action.special{margin-bottom:0}@media (pointer:coarse),(max-width:800px){.touch-controls{display:flex}.controls-hint{display:none}.top-hud{top:2%;left:3%;right:3%}.portrait{width:40px;height:40px;font-size:28px}.player-card{gap:7px}.eyebrow{font-size:8px}.health-track{height:9px}.small-label{font-size:7px}.stage-title{font-size:15px}.stage-card{min-width:125px}.stage-progress{margin-top:4px}.score-value{font-size:18px}.combo{font-size:7px}.boss-hud{top:12%;left:25%;right:25%}.boss-name{font-size:10px}.boss-track{height:10px}.title-kicker{font-size:8px;letter-spacing:.25em}.title-mark h1{font-size:clamp(54px,13vw,100px)}.title-rule{margin-top:17px}.intro-copy{font-size:16px;margin:16px 0 12px}.stage-chips{gap:4px;margin-bottom:14px}.stage-chips span{font-size:7px;padding:5px}.start-button{font-size:16px;padding:11px 22px}.overlay-note{font-size:7px;margin-top:15px}.overlay-foot{font-size:7px}.toast{top:22%;font-size:9px}}
 @media (max-width:520px){.top-hud{align-items:flex-start}.player-card,.score-card{width:30%}.stage-card{min-width:90px;padding-top:1px}.stage-title{font-size:12px}.stage-card .eyebrow{font-size:7px}.score-value{font-size:15px}.portrait{width:32px;height:32px;font-size:22px}.player-card{gap:5px}.small-label{display:none}.health-track{margin-top:4px}.touch-controls{bottom:4%}.dpad{transform:scale(.8);transform-origin:bottom left}.action{width:56px;height:56px}.action.special{width:48px;height:48px}.action-pad{gap:7px}.title-mark h1{font-size:58px}.stage-chips{max-width:330px}.stage-chips span{font-size:6px}.intro-copy{font-size:14px}.overlay-foot{bottom:2%}.overlay-note{font-size:6px}}
